initial_owner.text:
ResendEntry e;

e.dest = targets.front ().first;
e.seq = targets.front ().second;
e.dscp = 0;
e.frame = frame;
e.resendCount = 0;
e.lastTxTime = Seconds (0.0);
e.initialTxConfirmed = false;
e.flowControlTracked =
  flowControlTracked;

mac_sent.text:
  void NotifyMacFrameSent (
    CsrNodeId dest,
    uint16_t seq,
    Time sentAt)
  {
    ResendEntry *entry =
      FindResendEntry (dest, seq);

    if (entry == nullptr)
      {
        // br_hop retains one handle to the most recently scheduled resend
        // timer.  A MAC sent indication without a matching resend entry still
        // installs the fallback global scan when that handle is no longer
        // pending (notably after resend-queue overflow).
        if (!m_lastResendTimerEvent.IsPending ())
          {
            Time due = sentAt + m_resendTime + CsrOpnetTic ();
            Time delay =
              due > Simulator::Now ()
                ? due - Simulator::Now ()
                : Seconds (0.0);
            m_lastResendTimerEvent =
              Simulator::Schedule (
                delay,
                &CsrHopLayer::CheckResend,
                this);
          }
        return;
      }

    entry->lastTxTime = sentAt;
    entry->initialTxConfirmed = true;

    std::cout << "[HOP " << m_nodeId
              << "] MAC sent confirmation"
              << " dest=" << dest
              << " seq=" << seq
              << " transmission="
              << (entry->resendCount + 1)
              << " sentAt="
              << sentAt.GetSeconds ()
              << std::endl;

    Time wait =
      entry->resendCount >= m_maxNumResend
        ? m_resendTime + m_resendTime
        : m_resendTime;

    Time due = sentAt + wait + CsrOpnetTic ();
    Time delay =
      due > Simulator::Now ()
        ? due - Simulator::Now ()
        : Seconds (0.0);

    // OPNET schedules one RESEND_TIMER event for every br_Mac_Hop_Inst at the
    // nominal resend/final-ACK deadline plus one 36-MHz TIC.  Keeping these
    // events independent preserves the source's list-wide sweep behavior: a
    // stale or earlier timer can process every entry whose nominal deadline
    // has passed, including entries less than one TIC apart.
    m_lastResendTimerEvent =
      Simulator::Schedule (
        delay,
        &CsrHopLayer::CheckResend,
        this);
  }

  bool CanAcceptDataGlobally () const
  {
    // Legacy permits one final transfer while pending_pk_count is 16,
    // then blocks after SendData() raises the count to 17.
    return m_pendingDataCount <=
      HOP_PENDING_MAX_THRESHOLD;
  }

  bool CanSendToHop (CsrNodeId dest)
  {
    FlowCtrlEntry &e = GetFlowCtrlEntry (dest);

    bool neighborCanSend =
      e.outstanding <=
        e.threshold;

    // Legacy NWK computes:
    // FLOW_CTRL_MAX_THRESHOLD - pending_pk_count + 1.
    // Therefore pending=16 may admit one final packet,
    // producing pending=17 and congestion.
    bool nodeCanSend =
      CanAcceptDataGlobally ();

    bool canSend =
      neighborCanSend &&
      nodeCanSend;

    std::cout << "[HOP " << m_nodeId
              << "] CanSendToHop dest="
              << dest
              << " outstanding="
              << e.outstanding
              << " threshold="
              << e.threshold
              << " effectiveWindow="
              << (e.threshold + 1)
              << " pendingData="
              << m_pendingDataCount
              << " globalLimit="
              << HOP_PENDING_MAX_THRESHOLD
              << " neighborOK="
              << (neighborCanSend ? 1 : 0)
              << " nodeOK="
              << (nodeCanSend ? 1 : 0)
              << " -> "
              << (canSend ? "YES" : "NO")
              << std::endl;

    return canSend;
  }

private:
  struct ResendTarget
  {
    CsrNodeId dest {0};
    uint16_t seq {0};
    bool acked {false};
  };

  struct ResendEntry
  {
    CsrNodeId dest;
    uint16_t seq;
    uint8_t dscp;
    Ptr<Packet> frame;
    uint32_t resendCount;
    Time lastTxTime;
    bool initialTxConfirmed {false};
    std::vector<ResendTarget> targets;

    // Legacy network flow control applies to ordinary
    // DATA traffic, not reliable routing/control packets.
    bool flowControlTracked {false};

    // Keep NWK source/destination bookkeeping outside the encrypted frame so
    // ACK, DACK, and final-timeout completion can release the exact flow.
    bool networkFlowMetadataValid {false};
    CsrNodeId networkSource {0};
    CsrNodeId networkDestination {0};

    // Routing callback metadata remains plaintext even when the resend frame
    // carries a Group16-protected CsrHelloHeader.
    bool routingMetadataValid {false};
    uint32_t routingSequence {0};
    CsrRoutingOperation routingOperation {CsrRoutingOperation::None};
    uint8_t routingSection {0};
    uint8_t routingTotalSections {1};

    // NeighborCheck callback metadata remains plaintext even when the resend
    // frame carries a Pairwise16-protected CsrHelloHeader.
    bool neighborCheckMetadataValid {false};
    CsrNeighborCheckType neighborCheckType {CsrNeighborCheckType::None};
    uint32_t neighborCheckDiscoverySequence {0};
  };

retry_pass.text:
// Source check_resend() completes its full deletion pass before beginning
// the retransmission pass.  Preserve that same-time ordering so released
// capacity and timeout callbacks precede any newly queued resend.
for (auto &e : m_resendQueue)
  {
    if (!e.initialTxConfirmed ||
        e.resendCount >= m_maxNumResend ||
        now - e.lastTxTime < m_resendTime)
      {
        continue;
      }

    NS_LOG_INFO ("Hop " << m_nodeId << " resending dest="
                        << e.dest << " seq=" << e.seq
                        << " dscp=" << unsigned (e.dscp)
                        << " attempt=" << (e.resendCount + 1));

    e.resendCount++;

    // Keep the legacy provisional timestamp.  br_hop records the time it
    // hands a retransmission to MAC, then br_Mac_Hop_Inst replaces it with
    // the actual sent time when transmission occurs.
    e.lastTxTime = now;

    m_mac->EnqueueTxFrame (e.frame->Copy (), e.dest,
                           e.dscp, /*ackable*/ true);
  }

retry_pass_and_existing_option.text:
function checkResends(obj)
    keys=obj.ResendOrder;
    % Source final-expiration pass precedes all resend admissions.
    for n=1:numel(keys)
        key=keys{n}; if ~isKey(obj.Resends,key), continue; end
        e=obj.Resends(key);
        if e.Confirmed && e.ResendCount>=obj.Config.MaxResends && ...
                obj.Scheduler.Now-e.LastTxSeconds>=2*obj.Config.ResendSeconds
            obj.failEntry(key,e,'retry_exhausted');
        end
    end
    keys=obj.ResendOrder;
    for n=1:numel(keys)
        key=keys{n}; if ~isKey(obj.Resends,key), continue; end
        e=obj.Resends(key);
        if ~e.Confirmed || e.ResendCount>=obj.Config.MaxResends || ...
                obj.Scheduler.Now-e.LastTxSeconds<obj.Config.ResendSeconds
            continue
        end
        e.ResendCount=e.ResendCount+1;
        e.Frame.RetryCount=e.ResendCount;
        e.LastTxSeconds=obj.Scheduler.Now;
        % Source DATA keeps initial-TX confirmation after handing a
        % retry to MAC. A later list-wide scan can use this provisional
        % time even if that retry is still queued. No new timer is
        % installed here; actual MAC sent indications drive scans.
        e.Confirmed=strcmp(e.Frame.Kind,'DATA') && obj.nativeProvisional();
        obj.Resends(key)=e;
        if strcmp(e.Frame.Kind,'CONTROL'), obj.increment('ControlRetransmissions');
        else, obj.increment('Retransmissions'); end
        obj.emit('hop_retry',e.Frame,struct('ResendCount',e.ResendCount));
        if ~obj.enqueue(e.Frame)
            obj.increment('MacAdmissionRejected');
            obj.failEntry(key,e,'mac_queue_full');
        end
    end
end
function enabled = nativeProvisional(obj)
    enabled=strcmp(obj.Config.DataQueuedRetryPolicy,'native-provisional');
end

mac_sent.text:
function notifySent(obj,frame)
    % HOP never starts an initial ACK clock at MAC queue admission.
    isControl=strcmp(frame.Kind,'CONTROL');
    if ~isControl && ~strcmp(frame.Kind,'DATA'), return; end
    if isControl, obj.increment('ControlTransmitted'); else, obj.increment('Transmitted'); end
    if ~frame.AckRequired
        if isControl
            for n=1:numel(frame.DestinationIds)
                obj.controlResult(frame.Control,frame.DestinationIds(n),true, ...
                    n==numel(frame.DestinationIds),[]);
            end
            obj.increment('ControlCompleted');
        else, obj.terminal(frame.App,true,'sent_no_ack'); end
        return
    end
    key=entryKey(frame.DestinationId,frame.Sequence);
    if ~isKey(obj.Resends,key)
        % Native HOP retains only the latest installed timer handle.
        % An unmatched DATA sent indication may restart the shared
        % scan after that handle has fired; it never restores custody.
        if ~isControl && obj.nativeProvisional() && ~obj.LastResendTimerPending
            obj.scheduleResendScan(obj.Config.ResendSeconds);
        end
        return
    end
    e=obj.Resends(key); e.LastTxSeconds=obj.Scheduler.Now; e.Confirmed=true;
    obj.Resends(key)=e;
    wait=obj.Config.ResendSeconds;
    if e.ResendCount>=obj.Config.MaxResends, wait=2*wait; end
    if obj.nativeProvisional()
        obj.scheduleResendScan(wait);
    else
        obj.Scheduler.scheduleAt(obj.Scheduler.Now+wait+obj.Config.TicSeconds, ...
            @()obj.checkResends());
    end
    obj.emit('hop_sent',frame,struct('ResendCount',e.ResendCount, ...
        'AckWaitSeconds',wait));
end
